import logging
from typing import Union, Optional
from uuid import UUID

import requests
import urllib3

logging.getLogger("urllib3").setLevel(logging.WARNING)
urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)

logger = logging.getLogger("taf.vran.vdu.enb.rest")
logger.addHandler(logging.NullHandler())

def log_sending_message(
    request_id: UUID,
    endpoint: str,
    headers: Union[dict, None],
    method: str,
    connection_id: str,
    params: Optional[dict] = None,
    json: Optional[dict] = None,
    data: Union[str, dict, None] = None,
    log_payload: bool = True,
) -> None:
    """
    Logs details of the message that is being sent.

    :param UUID request_id: UUID of the request
    :param str endpoint: URL of the endpoint
    :param Union[dict, None] headers: Headers of the request
    :param str method: HTTP method of the request, for example: "GET", "POST", "PUT", "PATCH", "DELETE"
    :param str connection_id: ID of the connection, for example: "default_133148936573184"
    :param dict params: Query parameters of the request, defaults to None
    :param dict json: JSON data of the request, defaults to None
    :param Union[str, dict, None] data: Data of the request, defaults to None
    :param bool log_payload: If True, request payload is logged, defaults to True
    """
    extra = {
        "http_request": {
            "request_id": str(request_id),
            "method": method,
            "url": endpoint,
            "query_params": params if log_payload else None,
            "data": data if log_payload else None,
            "headers": headers,
            "json": json,
            "connection_id": connection_id,
        }
    }

    logger.debug(f"Sending message: {extra}", extra=extra)


def log_received_response(
    request_id: UUID,
    response: requests.Response,
    endpoint: str,
    method: str,
    connection_id: str
) -> None:
    """
    Logs details of the response that is being received.

    :param UUID request_id: UUID of the request
    :param Union[dict, bytes] response: Response of the request
    :param str endpoint: URL of the endpoint, for example: "https://10.42.126.110:443/api/sec/v1/login"
    :param str method: HTTP method of the request, for example: "GET", "POST", "PUT", "PATCH", "DELETE"
    :param connection_id: ID of the connection, for example: "default_133148936573184"
    """
    msg = {
        "http_response": {
            "request_id": str(request_id),
            "method": method,
            "url": endpoint,
            "status_code": response.status_code,
            "reason": response.reason,
            "connection_id": connection_id,
        }
    }

    extra = _prepare_extra(msg, response)
    msg["http_response"]["body"] = _trim_response_content(response)

    logger.debug(f"Received response: {msg}", extra=extra)


def _trim_response_content(response: requests.Response) -> str:
    response_content = " ".join(response.content.decode("utf-8", "ignore").split())

    if len(response_content) > 1000:
        return response_content[:1000] + "..."

    return response_content


def _prepare_extra(msg, response):
    extra = msg.copy()
    if (response.headers["Content-Type"] == "application/json") and (
        len(response.content) > 0
    ):
        extra["http_response"]["body"] = response.json()
    else:
        extra["http_response"]["body"] = response.content

    return extra
